// ============================================
// FILTER ANOMALY EVENTS
// ============================================

const items = $input.all();
const anomalyEvents = [];

for (const item of items) {
  const data = item.json;

  // Parse event if stringified
  let event = data.event || data;
  if (typeof event === 'string') {
    try {
      event = JSON.parse(event);
    } catch (e) {
      continue;
    }
  }

  // Filter only reconciliation.anomaly events
  if (event.event === 'reconciliation.anomaly' || event.type === 'reconciliation.anomaly') {
    anomalyEvents.push({
      json: {
        event_id: data.id || `anomaly_${Date.now()}`,
        event_type: 'reconciliation.anomaly',
        guild_id: event.guild_id,
        anomaly_type: event.data?.anomaly_type || 'unknown',
        severity: event.data?.severity || 'warning',
        source: event.data?.source || 'reconciliation',
        description: event.data?.description || 'Anomalie détectée',
        details: event.data?.details || {},
        affected_user_id: event.data?.affected_user_id,
        affected_discord_id: event.data?.affected_discord_id,
        expected_value: event.data?.expected_value,
        actual_value: event.data?.actual_value,
        timestamp: event.timestamp || new Date().toISOString()
      }
    });
  }
}

return anomalyEvents.length > 0 ? anomalyEvents : [];

// ============================================
// PREPARE ADMIN ALERT EMBED
// ============================================

const data = $input.first().json;

// Severity colors and emojis
const severityConfig = {
  critical: { color: 0xE74C3C, emoji: '🚨', label: 'CRITIQUE' },
  error: { color: 0xE74C3C, emoji: '❌', label: 'ERREUR' },
  warning: { color: 0xF39C12, emoji: '⚠️', label: 'ATTENTION' },
  info: { color: 0x3498DB, emoji: 'ℹ️', label: 'INFO' }
};

const config = severityConfig[data.severity] || severityConfig.warning;

// Anomaly type labels
const anomalyTypeLabels = {
  subscription_mismatch: 'Désynchronisation abonnement',
  payment_missing: 'Paiement manquant',
  access_without_subscription: 'Accès sans abonnement',
  subscription_without_access: 'Abonnement sans accès',
  duplicate_subscription: 'Abonnement dupliqué',
  expired_access_active: 'Accès expiré encore actif',
  data_inconsistency: 'Incohérence de données',
  unknown: 'Anomalie inconnue'
};

const anomalyLabel = anomalyTypeLabels[data.anomaly_type] || data.anomaly_type;

// Build fields
const fields = [
  {
    name: '📋 Type',
    value: anomalyLabel,
    inline: true
  },
  {
    name: '📊 Source',
    value: data.source,
    inline: true
  },
  {
    name: '⏰ Détecté à',
    value: new Date(data.timestamp).toLocaleString('fr-FR'),
    inline: true
  }
];

// Add affected user if present
if (data.affected_discord_id) {
  fields.push({
    name: '👤 Utilisateur affecté',
    value: `<@${data.affected_discord_id}>`,
    inline: true
  });
}

// Add expected vs actual if present
if (data.expected_value !== undefined && data.actual_value !== undefined) {
  fields.push({
    name: '📌 Valeur attendue',
    value: String(data.expected_value),
    inline: true
  });
  fields.push({
    name: '📍 Valeur actuelle',
    value: String(data.actual_value),
    inline: true
  });
}

// Add details if present
if (data.details && Object.keys(data.details).length > 0) {
  const detailsStr = Object.entries(data.details)
    .map(([k, v]) => `**${k}:** ${v}`)
    .join('\n');
  fields.push({
    name: '🔍 Détails',
    value: detailsStr.substring(0, 1024),
    inline: false
  });
}

const embed = {
  title: `${config.emoji} [${config.label}] Anomalie Détectée`,
  description: data.description,
  color: config.color,
  fields: fields,
  footer: {
    text: `Event ID: ${data.event_id}`
  },
  timestamp: data.timestamp
};

return {
  embed: embed,
  event_id: data.event_id,
  severity: data.severity,
  anomaly_type: data.anomaly_type
};

// ============================================
// LOG ALERT RESULT
// ============================================

const response = $input.first().json;
const prepData = $('Prepare Alert Embed').first().json;

const success = !response.error && response.statusCode !== 500;

console.log(`Admin alert ${success ? 'sent' : 'failed'} - ${prepData.anomaly_type} (severity: ${prepData.severity})`);

return {
  success: success,
  event_id: prepData.event_id,
  anomaly_type: prepData.anomaly_type,
  severity: prepData.severity,
  alert_type: 'admin_anomaly'
};
